//! Golden tests: compare candle-swin outputs against PyTorch reference.
//!
//! Test data generated by `scripts/generate_golden_data.py` which runs the
//! BiRefNet Swin V1 PyTorch implementation and saves inputs, weights, and
//! expected outputs as safetensors files.

use candle_core::{DType, Device, Result, Tensor, Var};
use candle_nn::{VarBuilder, VarMap};
use std::collections::HashMap;

fn load_test_case(name: &str) -> HashMap<String, Tensor> {
    let path = format!("test-data/{name}.safetensors");
    let data = std::fs::read(&path).unwrap_or_else(|_| panic!("missing test data: {path}"));
    let tensors = safetensors::SafeTensors::deserialize(&data).unwrap();
    let device = &Device::Cpu;

    tensors
        .tensors()
        .into_iter()
        .map(|(name, view)| {
            let dtype = match view.dtype() {
                safetensors::Dtype::F32 => DType::F32,
                safetensors::Dtype::F64 => DType::F64,
                safetensors::Dtype::I64 => DType::I64,
                safetensors::Dtype::U32 => DType::U32,
                dt => panic!("unsupported dtype {dt:?} for tensor {name}"),
            };
            let tensor = Tensor::from_raw_buffer(view.data(), dtype, view.shape(), device).unwrap();
            (name.to_string(), tensor)
        })
        .collect()
}

fn assert_tensor_close(actual: &Tensor, expected: &Tensor, atol: f64) {
    let diff = actual
        .to_dtype(DType::F64)
        .unwrap()
        .sub(&expected.to_dtype(DType::F64).unwrap())
        .unwrap()
        .abs()
        .unwrap()
        .flatten_all()
        .unwrap()
        .max(0)
        .unwrap()
        .to_scalar::<f64>()
        .unwrap();
    assert!(
        diff < atol,
        "max abs diff: {diff}, tolerance: {atol}\nactual shape: {:?}, expected shape: {:?}",
        actual.dims(),
        expected.dims()
    );
}

/// Build a VarBuilder from "param.*" entries in the test data.
/// The "param." prefix is stripped so keys match candle-nn's expected names.
fn vb_from_params(data: &HashMap<String, Tensor>) -> (VarMap, VarBuilder) {
    let varmap = VarMap::new();
    {
        let mut data_map = varmap.data().lock().unwrap();
        for (key, tensor) in data {
            if let Some(param_name) = key.strip_prefix("param.") {
                data_map.insert(param_name.to_string(), Var::from_tensor(tensor).unwrap());
            }
        }
    }
    let vb = VarBuilder::from_varmap(&varmap, DType::F32, &Device::Cpu);
    (varmap, vb)
}

// ============================================================================
// PatchEmbed
// ============================================================================

#[test]
fn golden_patch_embed() -> Result<()> {
    let data = load_test_case("patch_embed");
    let (_varmap, vb) = vb_from_params(&data);

    let pe = candle_swin::patch_embed::PatchEmbed::new(4, 3, 96, true, vb)?;
    let output = pe.forward(&data["input"])?;

    assert_eq!(output.dims(), data["output"].dims());
    assert_tensor_close(&output, &data["output"], 1e-4);
    Ok(())
}

// ============================================================================
// PatchMerging
// ============================================================================

#[test]
fn golden_patch_merging() -> Result<()> {
    let data = load_test_case("patch_merging");
    let (_varmap, vb) = vb_from_params(&data);

    let h: usize = data["H"].to_scalar::<i64>()? as usize;
    let w: usize = data["W"].to_scalar::<i64>()? as usize;

    let pm = candle_swin::patch_merging::PatchMerging::new(96, vb)?;
    let (output, new_h, new_w) = pm.forward(&data["input"], h, w)?;

    assert_eq!(new_h, h / 2);
    assert_eq!(new_w, w / 2);
    assert_eq!(output.dims(), data["output"].dims());
    assert_tensor_close(&output, &data["output"], 1e-4);
    Ok(())
}

