#[test]
fn golden_swin_block_shifted() -> Result<()> {
    let data = load_test_case("swin_block_shifted");
    let (_varmap, vb) = vb_from_params(&data);

    let h: usize = data["H"].to_scalar::<i64>()? as usize;
    let w: usize = data["W"].to_scalar::<i64>()? as usize;

    let ws: usize = 7;
    let shift: usize = ws / 2;
    let block = candle_swin::swin_transformer_block::SwinTransformerBlock::new(
        96, 3, ws, shift, 4.0, true, 0.0, 0.0, vb,
    )?;

    let attn_mask = &data["attn_mask"];
    let output = block.forward(&data["input"], h, w, Some(attn_mask))?;

    assert_eq!(output.dims(), data["output"].dims());
    assert_tensor_close(&output, &data["output"], 1e-4);
    Ok(())
}

// ============================================================================
// Full SwinTransformer
// ============================================================================

#[test]
fn golden_swin_tiny_full() -> Result<()> {
    let data = load_test_case("swin_tiny_full");
    let (_varmap, vb) = vb_from_params(&data);

    let config = candle_swin::swin_transformer::SwinTransformerConfig {
        patch_size: 4,
        in_channels: 3,
        embed_dim: 96,
        depths: vec![2, 2, 2, 2], // Reduced depths matching test data
        num_heads: vec![3, 6, 12, 24],
        window_size: 7,
        mlp_ratio: 4.0,
        qkv_bias: true,
        drop_rate: 0.0,
        attn_drop_rate: 0.0,
        out_indices: vec![0, 1, 2, 3],
    };
    let model = candle_swin::SwinTransformer::new(&config, vb)?;
    let outputs = model.forward(&data["input"])?;

    assert_eq!(outputs.len(), 4);
    for i in 0..4 {
        let key = format!("output_{i}");
        let expected = &data[&key];
        assert_eq!(
            outputs[i].dims(),
            expected.dims(),
            "shape mismatch at stage {i}"
        );
        assert_tensor_close(&outputs[i], expected, 1e-3);
    }
    Ok(())
}

// ============================================================================
// BiRefNet pretrained Swin-L backbone
// ============================================================================

/// End-to-end test using BiRefNet's pretrained Swin-Large backbone weights.
///
/// Loads the official BiRefNet model's backbone (swin_v1_l) with real pretrained
/// weights (fp16 -> fp32), feeds a 384x384 input, and compares all 4 stage
/// outputs against PyTorch reference within 1e-2 tolerance.
///
/// This validates that the candle-swin implementation is numerically compatible
/// with the PyTorch Swin V1 used in BiRefNet production inference.
#[test]
fn golden_birefnet_swin_backbone() -> Result<()> {
    let data = load_test_case("birefnet_swin_backbone");
    let (_varmap, vb) = vb_from_params(&data);

    let config = candle_swin::swin_transformer::SwinTransformerConfig::large();
    let model = candle_swin::SwinTransformer::new(&config, vb)?;
    let outputs = model.forward(&data["input"])?;

    assert_eq!(outputs.len(), 4);

    let expected_shapes: [(usize, usize, usize, usize); 4] = [
        (1, 192, 96, 96),
        (1, 384, 48, 48),
        (1, 768, 24, 24),
        (1, 1536, 12, 12),
    ];

    for i in 0..4 {
        let key = format!("output_{i}");
        let expected = &data[&key];

        assert_eq!(
            outputs[i].dims4()?,
            expected_shapes[i],
            "shape mismatch at stage {i}"
        );
        assert_eq!(
            outputs[i].dims(),
            expected.dims(),
            "shape mismatch at stage {i}"
        );

        // Actual max error is ~1.85e-4 (fp32 rounding across deep network)
        assert_tensor_close(&outputs[i], expected, 1e-3);
    }
    Ok(())
}
